raw:
{
  "sentence": "水を飲みます。",
  "furigana": "みずをのみます。",
  "translation": "Bebo agua.",
  "note": "水 (みず) significa 'agua'. La partícula を marca el objeto directo del verbo 飲む (のむ, beber)."
}

{
  "sentence": "毎日電車で学校に行きます。",
  "furigana": "まいにちでんしゃでがっこうにいきます。",
  "translation": "Voy a la escuela en tren todos los días.",
  "note": "La partícula で indica el medio de transporte utilizado para realizar la acción."
}

{
  "sentence": "レストランの予約をしました。",
  "furigana": "レストランのよやくをしました。",
  "translation": "Hice una reservación en el restaurante.",
  "note": "予約をする es la forma más común de expresar 'hacer una reserva'. El verbo する convierte el sustantivo 予約 en una acción."
}

{
  "sentence": "友達はとても大切な存在です。",
  "furigana": "ともだちはとてもたいせつなそんざいです。",
  "translation": "Los amigos son una presencia muy importante.",
  "note": "大切な es la forma adjetival (adjetivo な) que modifica al sustantivo 存在. Expresa que algo tiene gran valor o importancia."
}

{
  "sentence": "レポートの締め切りは来週の金曜日です。",
  "furigana": "レポートのしめきりはらいしゅうのきんようびです。",
  "translation": "La fecha límite del informe es el viernes de la próxima semana.",
  "note": "締め切り (しめきり) significa 'fecha límite' o 'plazo'. Se usa frecuentemente en contextos académicos y laborales."
}

{
  "sentence": "この経験はきっと将来に役に立つと思います。",
  "furigana": "このけいけんはきっとしょうらいにやくにたつとおもいます。",
  "translation": "Creo que esta experiencia seguramente será útil en el futuro.",
  "note": "役に立つ (やくにたつ) es una expresión común que significa 'ser útil'. El patrón 〜と思います expresa la opinión o suposición del hablante."
}

{
  "sentence": "ビザの手続きには時間がかかるので、早めに準備してください。",
  "furigana": "ビザのてつづきにはじかんがかかるので、はやめにじゅんびしてください。",
  "translation": "Los trámites de visa toman tiempo, así que por favor prepárese con anticipación.",
  "note": "手続き (てつづき) significa 'trámite' o 'procedimiento'. Se usa frecuentemente con verbos como する (realizar) o かかる (tomar tiempo). La estructura 〜ので indica una razón o causa de manera natural y directa."
}

{
  "sentence": "政府は経済危機に対して緊急の措置を取った。",
  "furigana": "せいふはけいざいききにたいしてきんきゅうのそちをとった。",
  "translation": "El gobierno tomó medidas de emergencia ante la crisis económica.",
  "note": "措置(そち) significa 'medida' o 'disposición' y se usa frecuentemente en contextos formales o gubernamentales. La expresión 措置を取る es la colocación más común."
}

{
  "sentence": "わたしは日本語を勉強します。",
  "furigana": "わたしはにほんごをべんきょうします。",
  "translation": "Yo estudio japonés.",
  "note": "日本語 (にほんご) significa 'idioma japonés'. La partícula を marca el objeto directo del verbo 勉強します."
}

{
  "sentence": "彼女の顔を認識することができなかった。",
  "furigana": "かのじょのかおをにんしきすることができなかった。",
  "translation": "No pude reconocer su cara.",
  "note": "認識する significa 'reconocer' o 'identificar'. La estructura ～することができなかった expresa que algo no fue posible hacer en el pasado."
}

{
  "sentence": "この建物の安全を保護するために、カメラを設置した。",
  "furigana": "このたてもののあんぜんをほごするために、カメラをせっちした。",
  "translation": "Para proteger la seguridad de este edificio, instalamos cámaras.",
  "note": "保護（ほご）significa 'protección'. La construcción ～するために indica propósito ('para hacer ~')."
}

{
  "sentence": "彼は毎朝早く起きて、仕事の準備を務めている。",
  "furigana": "かれはまいあさはやくおきて、しごとのじゅんびをつとめている。",
  "translation": "Él se despierta temprano cada mañana y se esfuerza en prepararse para el trabajo.",
  "note": "務める (つとめる) significa 'esforzarse en cumplir con una responsabilidad' o 'desempeñar un rol'. Se diferencia de 勤める (つとめる), que significa 'trabajar en una empresa'."
}

{
  "sentence": "ちょっと待ってください。",
  "furigana": "ちょっとまってください。",
  "translation": "Por favor, espere un momento.",
  "note": "ちょっと significa 'un poco' o 'un momento'. Se usa frecuentemente para hacer peticiones más suaves y educadas."
}

{
  "sentence": "この花は毎年春に生まれます。",
  "furigana": "このはなはまいとしはるにうまれます。",
  "translation": "Esta flor nace cada primavera.",
  "note": "生まれる (うまれる) significa 'nacer'. Aquí se usa en presente habitual para describir algo que ocurre regularmente cada año."
}

{
  "sentence": "壁に絵を掛けてください。",
  "furigana": "かべにえをかけてください。",
  "translation": "Por favor, cuelga el cuadro en la pared.",
  "note": "掛ける puede significar 'colgar' algo en una superficie vertical, como una pared. Se usa con に para indicar el lugar donde se cuelga el objeto."
}

{
  "sentence": "新しいアパートの契約を結ぶために、不動産屋へ行った。",
  "furigana": "あたらしいアパートのけいやくをむすぶために、ふどうさんやへいった。",
  "translation": "I went to the real estate agency to sign a contract for a new apartment.",
  "note": "「契約を結ぶ」is a common collocación meaning 'to conclude/sign a contract'. The ために here expresses purpose."
}

{
  "sentence": "この仕事には経験が必要です。",
  "furigana": "このしごとにはけいけんがひつようです。",
  "translation": "Per questo lavoro è necessaria l'esperienza.",
  "note": "経験（けいけん）significa 'esperienza' e si usa spesso con が必要 ('è necessario') o する per formare il verbo 'fare esperienza'."
}

{
  "sentence": "出発する前に、チケットを確認してください。",
  "furigana": "しゅっぱつするまえに、チケットをかくにんしてください。",
  "translation": "Avant de partir, veuillez vérifier votre billet.",
  "note": "確認する (かくにんする) est un verbe composé (nom + する) signifiant 'vérifier' ou 'confirmer'. Il s'utilise souvent dans des contextes formels ou pratiques."
}
